package com.example.starter.api.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 依赖声明：闭区间 [minimumVersion, maximumVersion]，版本均为正整数。
 *
 * <p>exclusions 为边级排除名称（最多 3 个、不可重复）：经过该边之后，
 * 在其整个子图中忽略以这些名称为目标的边；排除不能移除该边目标本身。
 */
public record DependencySpec(
        @NotBlank String name,
        @Positive int minimumVersion,
        @Positive int maximumVersion,
        @Size(max = 3) List<@NotBlank String> exclusions) {

    public DependencySpec {
        exclusions = exclusions == null ? List.of() : List.copyOf(exclusions);
    }

    /** 无排除的依赖声明。 */
    public DependencySpec(String name, int minimumVersion, int maximumVersion) {
        this(name, minimumVersion, maximumVersion, List.of());
    }
}

package com.example.starter.api.dto;

import java.util.List;

/**
 * 响应中的依赖区间视图，exclusions 为该边声明的排除名称（升序）。
 */
public record DependencyView(String name, int minimumVersion, int maximumVersion,
                             List<String> exclusions) {

    public DependencyView {
        exclusions = exclusions == null ? List.of() : List.copyOf(exclusions);
    }
}

package com.example.starter.api.dto;

/**
 * 锁文件中实际保留的依赖边：fromName:fromVersion 声明的、指向 toName 的区间约束。
 */
public record LockEdgeResponse(String fromName, int fromVersion, String toName,
                               int minimumVersion, int maximumVersion) {
}

package com.example.starter.api.dto;

/**
 * 锁文件中的路径排除处置记录。
 *
 * @param outcome APPLIED=实际忽略了同名边；MISS=未命中（允许排除未知名称）
 * @param detail  人读理由：APPLIED 时列出被忽略的边，MISS 时为“未命中”
 */
public record LockExclusionResponse(String fromName, int fromVersion, String toName,
                                    String excludedName, String outcome, String detail) {
}

package com.example.starter.api.dto;

import java.time.Instant;
import java.util.List;

/**
 * 历史锁文件视图：entries 按名称升序，edges 为实际保留边，
 * exclusions 为路径排除处置记录；生成后不改写。
 */
public record LockFileResponse(
        long id,
        String rootName,
        int rootVersion,
        long repositoryVersion,
        Instant createdAt,
        List<LockEntryResponse> entries,
        List<LockEdgeResponse> edges,
        List<LockExclusionResponse> exclusions) {
}

