205	        if (root == null) {
206	            throw ApiException.notFound("根制品版本不存在: " + rootName + ":" + rootVersion);
207	        }
208	        if (root.withdrawn()) {
209	            throw ApiException.conflict("根制品版本已撤回: " + rootName + ":" + rootVersion);
210	        }
