213	        LockSolution solution = LockResolver.solve(snapshot, rootName, rootVersion);
214	        if (solution == null) {
215	            throw ApiException.unprocessable(
216	                    "不存在满足全部依赖区间的未撤回版本组合，无法锁定");
217	        }
218	
