220	        long lockFileId = repositoryDao.insertLockFile(rootName, rootVersion, currentVersion,
221	                currentRequestId.get(), now);
222	        solution.versions().forEach((n, v) -> repositoryDao.insertLockEntry(lockFileId, n, v));
223	        solution.edges().forEach(edge -> repositoryDao.insertLockEdge(lockFileId, edge));
224	        solution.exclusions().forEach(record -> repositoryDao.insertLockExclusion(lockFileId, record));
