227	        solution.versions().forEach((n, v) -> entries.add(new LockEntryResponse(n, v)));
228	        return new LockFileResponse(lockFileId, rootName, rootVersion, currentVersion, now,
229	                entries, toEdgeResponses(solution.edges()),
